class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        mod = 10**9 + 7
        ss = s + s

        if t not in ss:
            return 0

        n = len(s)

        if s == t:
            f0 = 1
            r = n // ss.find(s, 1)
        else:
            f0 = 0
            r = n // ss.find(s, 1)

        f1 = r - f0

        if k % 2 == 0:
            left = f1
        else:
            left = f0

        if k % 2 == 0:
            a1 = (n - 2) * r
        else:
            a1 = (n - 2) * (n - 1) * r

        q = (n - 1) ** 2

        if q == 1:
            ans = (a1 * (k // 2) + left) % mod
        else:
            ans = a1 * (pow(q, k // 2, mod * (q - 1)) - 1) // (q - 1) + left

        return ans % mod

